"""Threat detection engine for simulated authentication logs."""

from __future__ import annotations

import argparse
import hashlib
import ipaddress
import json
from collections import defaultdict
from dataclasses import asdict, dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path


@dataclass(frozen=True)
class SecurityEvent:
    """One validated authentication event."""

    timestamp: datetime
    event_type: str
    username: str
    source_ip: str


@dataclass(frozen=True)
class Alert:
    """A detection generated by one of the analysis rules."""

    rule_id: str
    severity: str
    source_ip: str
    start_time: str
    end_time: str
    event_count: int
    usernames: list[str]
    description: str

    def to_dict(self) -> dict:
        """Return the alert as a JSON-serializable dictionary."""
        return asdict(self)


def load_events(path: Path) -> list[SecurityEvent]:
    """Load and validate newline-delimited JSON authentication events."""
    events: list[SecurityEvent] = []

    with Path(path).open("r", encoding="utf-8") as file:
        for line_number, line in enumerate(file, start=1):
            if not line.strip():
                continue

            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    f"Invalid JSON on line {line_number}: {exc}"
                ) from exc

            try:
                if not isinstance(record, dict):
                    raise ValueError("each event must be a JSON object")

                timestamp_text = record["timestamp"]
                event_type = record["event_type"]
                username = record["username"]
                source_ip = record["source_ip"]

                if not isinstance(timestamp_text, str) or not timestamp_text.strip():
                    raise ValueError("timestamp must be a non-empty string")

                # Accept ISO-8601 timestamps ending in Z and normalize to UTC.
                timestamp = datetime.fromisoformat(
                    timestamp_text.strip().replace("Z", "+00:00")
                )
                if timestamp.tzinfo is None:
                    raise ValueError("timestamp must include a timezone")

                if event_type not in {"login_success", "login_failure"}:
                    raise ValueError("unsupported event_type")

                if not isinstance(username, str) or not username.strip():
                    raise ValueError("username must be a non-empty string")

                if not isinstance(source_ip, str) or not source_ip.strip():
                    raise ValueError("source_ip must be a non-empty IP address string")

                # Normalize equivalent IP address representations consistently.
                normalized_ip = str(ipaddress.ip_address(source_ip.strip()))

                events.append(
                    SecurityEvent(
                        timestamp=timestamp.astimezone(timezone.utc),
                        event_type=event_type,
                        username=username.strip(),
                        source_ip=normalized_ip,
                    )
                )

            except (KeyError, TypeError, ValueError, AttributeError) as exc:
                raise ValueError(
                    f"Invalid event on line {line_number}: {exc}"
                ) from exc

    return sorted(events, key=lambda event: event.timestamp)


def detect_brute_force(
    events: list[SecurityEvent],
    threshold: int = 5,
    window_minutes: int = 5,
) -> list[Alert]:
    """Detect repeated failed logins against one account from one IP."""
    if threshold < 1 or window_minutes < 1:
        raise ValueError("threshold and window_minutes must be positive")

    failures: dict[tuple[str, str], list[SecurityEvent]] = defaultdict(list)
    for event in events:
        if event.event_type == "login_failure":
            failures[(event.source_ip, event.username)].append(event)

    alerts: list[Alert] = []
    window = timedelta(minutes=window_minutes)

    for (source_ip, username), attempts in failures.items():
        attempts.sort(key=lambda item: item.timestamp)
        left = 0
        alert_active = False

        for right, event in enumerate(attempts):
            while event.timestamp - attempts[left].timestamp > window:
                left += 1

            count = right - left + 1
            if count < threshold:
                alert_active = False
                continue

            if alert_active:
                continue

            burst = attempts[left : right + 1]
            alerts.append(
                Alert(
                    rule_id="BRUTE_FORCE",
                    severity="high",
                    source_ip=source_ip,
                    start_time=burst[0].timestamp.isoformat(),
                    end_time=burst[-1].timestamp.isoformat(),
                    event_count=len(burst),
                    usernames=[username],
                    description=(
                        f"{len(burst)} failed logins against account "
                        f"{username!r} from one IP within {window_minutes} minutes."
                    ),
                )
            )
            alert_active = True

    return alerts


def detect_password_spraying(
    events: list[SecurityEvent],
    min_usernames: int = 5,
    window_minutes: int = 10,
) -> list[Alert]:
    """Detect failed logins against multiple accounts from one IP."""
    if min_usernames < 2 or window_minutes < 1:
        raise ValueError(
            "min_usernames must be at least 2 and window_minutes positive"
        )

    failures: dict[str, list[SecurityEvent]] = defaultdict(list)
    for event in events:
        if event.event_type == "login_failure":
            failures[event.source_ip].append(event)

    alerts: list[Alert] = []
    window = timedelta(minutes=window_minutes)

    for source_ip, attempts in failures.items():
        attempts.sort(key=lambda item: item.timestamp)
        left = 0
        alert_active = False

        for right, event in enumerate(attempts):
            while event.timestamp - attempts[left].timestamp > window:
                left += 1

            burst = attempts[left : right + 1]
            usernames = sorted({item.username for item in burst})

            if len(usernames) < min_usernames:
                alert_active = False
                continue

            if alert_active:
                continue

            alerts.append(
                Alert(
                    rule_id="PASSWORD_SPRAYING",
                    severity="high",
                    source_ip=source_ip,
                    start_time=burst[0].timestamp.isoformat(),
                    end_time=burst[-1].timestamp.isoformat(),
                    event_count=len(burst),
                    usernames=usernames,
                    description=(
                        f"Failed logins against {len(usernames)} different accounts "
                        f"within {window_minutes} minutes."
                    ),
                )
            )
            alert_active = True

    return alerts


def analyze_events(events: list[SecurityEvent]) -> list[Alert]:
    """Run all enabled detection rules and return alerts chronologically."""
    alerts = detect_brute_force(events)
    alerts.extend(detect_password_spraying(events))
    return sorted(alerts, key=lambda alert: (alert.start_time, alert.rule_id))


def sha256_file(path: Path, chunk_size: int = 1024 * 1024) -> str:
    """Calculate a file's SHA-256 hash without loading it all into memory."""
    if chunk_size < 1:
        raise ValueError("chunk_size must be positive")

    digest = hashlib.sha256()
    with Path(path).open("rb") as file:
        for chunk in iter(lambda: file.read(chunk_size), b""):
            digest.update(chunk)
    return digest.hexdigest()


def build_incident_timeline(
    events: list[SecurityEvent],
    alerts: list[Alert],
) -> list[dict]:
    """Reconstruct events in chronological order with linked alerts."""
    timeline: list[dict] = []

    for event in sorted(events, key=lambda item: item.timestamp):
        linked_rules: list[str] = []

        for alert in alerts:
            start = datetime.fromisoformat(alert.start_time)
            end = datetime.fromisoformat(alert.end_time)
            if (
                event.event_type == "login_failure"
                and event.source_ip == alert.source_ip
                and event.username in alert.usernames
                and start <= event.timestamp <= end
            ):
                linked_rules.append(alert.rule_id)

        timeline.append(
            {
                "timestamp_utc": event.timestamp.isoformat(),
                "event_type": event.event_type,
                "username": event.username,
                "source_ip": event.source_ip,
                "linked_alert_rules": sorted(set(linked_rules)),
            }
        )

    return timeline


def build_investigation_report(
    source_path: Path,
    events: list[SecurityEvent],
    alerts: list[Alert],
) -> dict:
    """Build a JSON-serializable forensic investigation report."""
    severity_counts: dict[str, int] = {}
    for alert in alerts:
        severity_counts[alert.severity] = severity_counts.get(alert.severity, 0) + 1

    ordered_events = sorted(events, key=lambda event: event.timestamp)
    time_range = None
    if ordered_events:
        time_range = {
            "start_utc": ordered_events[0].timestamp.isoformat(),
            "end_utc": ordered_events[-1].timestamp.isoformat(),
        }

    return {
        "report_version": "1.0",
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "evidence": {
            "file_name": Path(source_path).name,
            "sha256": sha256_file(source_path),
            "event_count": len(events),
            "event_time_range_utc": time_range,
        },
        "summary": {
            "alert_count": len(alerts),
            "severity_counts": severity_counts,
        },
        "alerts": [alert.to_dict() for alert in alerts],
        "timeline": build_incident_timeline(ordered_events, alerts),
        "limitations": [
            "Detection alerts are heuristic indicators, not proof of an attack.",
            "The SHA-256 hash identifies the input file at analysis time; "
            "it does not independently prove authenticity or chain of custody.",
        ],
    }


def main() -> int:
    """Command-line entry point for the detection engine."""
    parser = argparse.ArgumentParser(
        description="Analyze authentication logs for suspicious activity."
    )
    parser.add_argument(
        "log_file",
        type=Path,
        help="Path to a newline-delimited JSON log file",
    )
    parser.add_argument(
        "--report",
        type=Path,
        help="Optional path for a JSON investigation report",
    )
    args = parser.parse_args()

    try:
        events = load_events(args.log_file)
        alerts = analyze_events(events)

        if args.report:
            report = build_investigation_report(args.log_file, events, alerts)
            args.report.parent.mkdir(parents=True, exist_ok=True)
            args.report.write_text(
                json.dumps(report, indent=2),
                encoding="utf-8",
            )
    except (OSError, ValueError) as exc:
        print(f"Error: {exc}")
        return 1

    print(f"Events analyzed: {len(events)}")
    print(f"Alerts generated: {len(alerts)}")
    print(json.dumps([alert.to_dict() for alert in alerts], indent=2))

    if not alerts:
        print("No suspicious activity detected.")

    if args.report:
        print(f"Investigation report saved to: {args.report}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
